
import pandas as pd
import pytest


@pytest.fixture(scope="module")
def prepared_data():
    """Load the dataset generated by the DVC preparation stage."""
    return pd.read_csv("data/california_housing.csv")


def test_prepared_dataset_schema(prepared_data):
    """Verify required columns and dataset size."""
    required_columns = [
        "MedInc",
        "HouseAge",
        "AveRooms",
        "AveBedrms",
        "Population",
        "AveOccup",
        "Latitude",
        "Longitude",
        "IncomeCategory",
        "MedHouseValue",
    ]

    assert len(prepared_data) == 20640
    assert set(required_columns) == set(prepared_data.columns)


def test_target_is_valid(prepared_data):
    """Verify the target is numeric, present, and positive."""
    target = prepared_data["MedHouseValue"]

    assert pd.api.types.is_numeric_dtype(target)
    assert target.notna().all()
    assert (target > 0).all()


def test_numeric_ranges_are_valid(prepared_data):
    """Verify expected ranges for key housing features."""
    df = prepared_data

    assert df["MedInc"].dropna().ge(0).all()
    assert df["HouseAge"].dropna().between(1, 52).all()
    assert df["Latitude"].dropna().between(32, 42).all()
    assert df["Longitude"].dropna().between(-125, -114).all()